public class Main {
    static int hitungTotal(int harga, int jumlah) {
        return harga * jumlah;
    }


    static int hitungKembalian(int bayar, int total) {
        return bayar - total;
    }

    public static void main(String[] args) {
        int total = hitungTotal(5000, 2);
        System.out.println("Total: " + total);
        System.out.println("Kembalian: " + hitungKembalian(20000, total));
    }
}

public class Main {
    static int hitungTotal(int harga, int jumlah) {
        return harga * jumlah;
    }


    static int hitungKembalian(int bayar, int total) {
        return bayar - total;
    }


    static boolean uangCukup(int bayar, int total) {
        return bayar >= total;
    }

    public static void main(String[] args) {
        int total = hitungTotal(5000, 2);
        System.out.println("Total: " + total);
        System.out.println("Kembalian: " + hitungKembalian(20000, total));
        System.out.println("Uang cukup: " + uangCukup(20000, total));
    }
}

public class Main {
    static int hitungTotal(int harga, int jumlah) {
        return harga * jumlah;
    }


    static int hitungKembalian(int bayar, int total) {
        return bayar - total;
    }


    static boolean uangCukup(int bayar, int total) {
        return bayar >= total;
    }

    public static void main(String[] args) {
        int total = hitungTotal(5000, 2);
        System.out.println("Total: " + total);
        System.out.println("Kembalian: " + hitungKembalian(20000, total));
        System.out.println("Uang cukup: " + uangCukup(20000, total));
        System.out.println("Total semua: " + (hitungTotal(5000, 2) + hitungTotal(4000, 3)));
    }
}

